    /// All recovered Dirigo types, then the synthetic Maraflow types. A Maraflow name that collides with a Dirigo
    /// one stays reachable by GUID; `byName` keeps the Dirigo entry so existing lookups do not change.
    public static let all: [BlockTypeInfo] = base + MaraflowCatalog.infos

    /// Registry keyed by block-type GUID.
    public static let byGuid: [UUID: BlockTypeInfo] = {
        var map: [UUID: BlockTypeInfo] = [:]
        for info in all { map[info.guid] = info }
        return map
    }()

    /// Registry keyed by lowercased Dirigo block name.
    public static let byName: [String: BlockTypeInfo] = {
        var map: [String: BlockTypeInfo] = [:]
        for info in all where map[info.blockName.lowercased()] == nil { map[info.blockName.lowercased()] = info }
        return map
    }()

    public static func info(forGuid guid: UUID) -> BlockTypeInfo? { byGuid[guid] }

    public static func info(forBlockName name: String) -> BlockTypeInfo? {
        byName[name.lowercased()]
    }

    /// Block types the original library registers that this reimplementation does not
    /// provide a class for. Instances of these run as `UnresolvedBlock`.
    public static var unimplemented: [BlockTypeInfo] {
        all.filter { !$0.isImplemented && $0.category != "Reimplementation" }
    }

    /// True when this reimplementation can simulate the type.
    public static func isImplemented(guid: UUID) -> Bool {
        byGuid[guid]?.isImplemented ?? false
    }
}
